function trap(height: number[]): number {
  let left = 0;
  let right = height.length - 1;
  let leftMax = 0; // самый высокий столбик на отрезке [0, left]
  let rightMax = 0; // самый высокий столбик на отрезке [right, n - 1]
  let water = 0;

  while (left < right) {
    if (height[left] < height[right]) {
      // Справа есть стенка выше height[left], значит уровень воды
      // над left определяется только leftMax
      leftMax = Math.max(leftMax, height[left]);
      water += leftMax - height[left];
      left++;
    } else {
      // Симметрично: слева есть стенка не ниже height[right],
      // уровень над right определяется rightMax
      rightMax = Math.max(rightMax, height[right]);
      water += rightMax - height[right];
      right--;
    }
  }

  return water;
}

// Время: O(n) — один проход двумя указателями
// Память: O(1)
